import java.util.*;

class Solution {
  public int minimumSemesters(int n, int[][] relations) {
    List<List<Integer>> next = new ArrayList<>();
    for (int i = 0; i <= n; i++) next.add(new ArrayList<>());
    int[] indegree = new int[n + 1];
    for (int[] r : relations) {
      next.get(r[0]).add(r[1]);
      indegree[r[1]]++;
    }
    Deque<Integer> q = new ArrayDeque<>();
    for (int i = 1; i <= n; i++) if (indegree[i] == 0) q.add(i);
    int semesters = 0, taken = 0;
    while (!q.isEmpty()) {
      semesters++;
      for (int size = q.size(); size > 0; size--) {
        int c = q.poll();
        taken++;
        for (int nb : next.get(c)) if (--indegree[nb] == 0) q.add(nb);
      }
    }
    return taken == n ? semesters : -1; // a cycle leaves courses untaken
  }
}
